Rules.InvariantScript:
// ======================================================
// btnPHR_RebuildActiveTab.OnSelect
// PHR - Rebuild active L1 tab optimized
// ======================================================

If(
    IsBlank(varPHR_SelectedL1NodeId) && CountRows(colPHR_HeaderL1Base) > 0,
    Set(varPHR_SelectedL1NodeId, First(colPHR_HeaderL1Base).L1NodeId);
    Set(varPHR_SelectedL1Label, First(colPHR_HeaderL1Base).L1Label)
);

If(
    IsBlank(varPHR_SelectedL1NodeId),
    Clear(colPHR_HeaderL4_Active);
    Clear(colPHR_HeaderL3_Active);
    Clear(colPHR_HeaderL2_Active);
    Clear(colPHR_HeaderL1_Active);
    Clear(colPHR_RowCells_Active);
    Clear(colPHR_RowStatus);
    Exit()
);

// 1) Build active L4 columns using Index instead of CountRows(Filter(...))
ClearCollect(
    colPHR_HeaderL4_Active_Base,
    SortByColumns(
        Filter(
            colPHR_HeaderL4Indexed,
            Text(L1NodeId) = Text(varPHR_SelectedL1NodeId)
        ),
        "ColIndex",
        SortOrder.Ascending
    )
);

ClearCollect(
    colPHR_HeaderL4_Active,
    ForAll(
        Sequence(CountRows(colPHR_HeaderL4_Active_Base)) As seq,
        Patch(
            Index(colPHR_HeaderL4_Active_Base, seq.Value),
            {
                LocalColIndex: seq.Value,
                StartX: (seq.Value - 1) * varPHR_ColW,
                WidthPx: varPHR_ColW
            }
        )
    )
);

// 2) Build active L3 groups
ClearCollect(
    colPHR_HeaderL3_Active,
    SortByColumns(
        AddColumns(
            GroupBy(
                colPHR_HeaderL4_Active,
                L1NodeId,
                L1Label,
                L1SortOrder,
                L2NodeId,
                L2Label,
                L2SortOrder,
                L3NodeId,
                L3Label,
                L3SortOrder,
                Rows
            ),
            StartCol, Min(Rows, LocalColIndex),
            EndCol, Max(Rows, LocalColIndex),
            ColCount, CountRows(Rows),
            StartX, (Min(Rows, LocalColIndex) - 1) * varPHR_ColW,
            WidthPx, CountRows(Rows) * varPHR_ColW
        ),
        "StartCol",
        SortOrder.Ascending
    )
);

// 3) Build active L2 groups
ClearCollect(
    colPHR_HeaderL2_Active,
    SortByColumns(
        AddColumns(
            GroupBy(
                colPHR_HeaderL4_Active,
                L1NodeId,
                L1Label,
                L1SortOrder,
                L2NodeId,
                L2Label,
                L2SortOrder,
                Rows
            ),
            StartCol, Min(Rows, LocalColIndex),
            EndCol, Max(Rows, LocalColIndex),
            ColCount, CountRows(Rows),
            StartX, (Min(Rows, LocalColIndex) - 1) * varPHR_ColW,
            WidthPx, CountRows(Rows) * varPHR_ColW
        ),
        "StartCol",
        SortOrder.Ascending
    )
);

// 4) Build active L1 group
ClearCollect(
    colPHR_HeaderL1_Active,
    SortByColumns(
        AddColumns(
            GroupBy(
                colPHR_HeaderL4_Active,
                L1NodeId,
                L1Label,
                L1SortOrder,
                Rows
            ),
            StartCol, Min(Rows, LocalColIndex),
            EndCol, Max(Rows, LocalColIndex),
            ColCount, CountRows(Rows),
            StartX, 0,
            WidthPx, CountRows(Rows) * varPHR_ColW
        ),
        "StartCol",
        SortOrder.Ascending
    )
);

// 5) Build active row cells
ClearCollect(
    colPHR_RowCells_Active,
    Ungroup(
        ForAll(
            colPHR_Subsystems As s,
            With(
                {
                    _subMetrics:
                        Filter(
                            colPHR_Metrics,
                            SubsystemCode = s.SubsystemCode
                        )
                },
                {
                    RowCells:
                        AddColumns(
                            colPHR_HeaderL4_Active As h,
                            SubsystemCode, s.SubsystemCode,
                            RowNo, s.RowNo,
                            CellValue,
                                Coalesce(
                                    LookUp(
                                        _subMetrics,
                                        MetricKey = h.MetricKey,
                                        MetricValue
                                    ),
                                    0
                                )
                        )
                }
            )
        ),
        RowCells
    )
);

// 6) Precalculate row status once
ClearCollect(
    colPHR_RowStatus,
    ForAll(
        colPHR_Subsystems As s,
        With(
            {
                _maxRemaining:
                    Coalesce(
                        Max(
                            Filter(
                                colPHR_RowCells_Active,
                                SubsystemCode = s.SubsystemCode &&
                                Upper(Text(MetricLabel)) in ["REM.", "REMAINING"]
                            ),
                            Value(CellValue)
                        ),
                        0
                    )
            },
            {
                SubsystemCode: s.SubsystemCode,
                MaxRemaining: _maxRemaining,
                StatusColor:
                    If(
                        _maxRemaining >= 20,
                        ColorValue("#DC2626"),
                        If(
                            _maxRemaining > 0,
                            ColorValue("#D97706"),
                            ColorValue("#16A34A")
                        )
                    ),
                StatusTooltip:
                    If(
                        _maxRemaining >= 20,
                        "Attention required · " & Text(_maxRemaining) & " remaining",
                        If(
                            _maxRemaining > 0,
                            "In progress · " & Text(_maxRemaining) & " remaining",
                            "Ready · no remaining items"
                        )
                    )
            }
        )
    )
);

// 7) Recalculate active widths
Set(
    varPHR_DataColsWidth_Active,
    Max(
        CountRows(colPHR_HeaderL4_Active) * varPHR_ColW,
        varPHR_ColW
    )
);

Set(
    varPHR_TotalGridWidth_Active,
    varPHR_StatusW + varPHR_SubsysW + varPHR_ActionsW + varPHR_DataColsWidth_Active
);

// 8) Reset horizontal scroll
Reset(sldPHR_HOffset_1);

